1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
32	// 给出的完整字符串逐字节参与比较，允许包含 U+0000 与非法 UTF-8 字节
33	// （后者靠记录中的 identity_raw 兜底字段跨重开保真）。不能用分隔符把两个
34	// 字段拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、
35	// 请求号 "c" 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
36	type idemIdentity struct {
37		submitter string
38		requestID string
39	}
40	
41	type Store struct {
42		dir string
43	
44		mu     sync.Mutex
45		jobs   []*storedJob // 严格按作业号（即提交先后）排列
46		byID   map[uint64]*storedJob
47		idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
48		nextID uint64
49		closed bool
50	
51		now func() time.Time
52	
53		runningID uint64
54		waitCh    chan struct{}
55		stopCh    chan struct{}
56		stopping  atomic.Bool
57		wg        sync.WaitGroup
58	
59		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
60		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
61		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
62		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
63	
64		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
65		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
66		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
67		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
68		persistFault func(j *storedJob) error
69	}
70	
71	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
72	//
73	// 恢复语义：
74	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
75	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
76	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
77	//   - 成功状态始终与完整归档同时可见。
78	func Open(dir string, opts ...Option) (*Store, error) {
79		if err := os.MkdirAll(dir, 0o700); err != nil {
80			return nil, err
81		}
82		jobs, maxID, err := loadDir(dir)
83		if err != nil {
84			return nil, err
85		}
86		s := &Store{
87			dir:    dir,
88			jobs:   jobs,
89			byID:   make(map[uint64]*storedJob),
90			idem:   make(map[idemIdentity]uint64),
91			nextID: maxID + 1,
92			now:    wallClock{}.Now,
93			waitCh: make(chan struct{}, 1),
94			stopCh: make(chan struct{}),
95		}
96		for _, opt := range opts {
97			opt(s)
98		}
99		for _, j := range jobs {
100			s.byID[j.id] = j
101			if j.requestID != "" {
102				s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
103			}
104		}
105		// 重建失败/取消作业对排队下游的阻断。
106		s.cascadeLocked()
107		s.wg.Add(1)
108		go s.worker()
109		return s, nil
110	}
111	
112	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
113	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
114	func (s *Store) Close() error {
115		s.mu.Lock()
116		if s.closed {
117			s.mu.Unlock()
118			return nil
119		}
120		s.closed = true
121		var running *storedJob
122		if s.runningID != 0 {
123			running = s.byID[s.runningID]
124		}
125		s.mu.Unlock()
126	
127		if s.stopping.CompareAndSwap(false, true) {
128			close(s.stopCh)
129		}
130		// 中止正在运行的计算。
131		if running != nil {
132			running.canceled.Store(true)
133		}
134		s.notify()
135		s.wg.Wait()
136		return nil
137	}
138	
139	// Submit 接受一次作业提交。
140	//
141	// 空序列返回 [ErrEmptySequence]；引用不存在的依赖返回
142	// [ErrDependencyNotFound]；同一提交人复用请求号但内容变化返回
143	// [ErrIdempotencyConflict]（同时返回原作业视图）——这些拒绝都不产生记录。
144	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
145	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
146		s.mu.Lock()
147		defer s.mu.Unlock()
148		if s.closed || s.stopping.Load() {
149			return nil, ErrStoreClosed
150		}
151		if len(req.Values) == 0 {
152			return nil, ErrEmptySequence
153		}
154		if err := s.validateDependenciesLocked(&req); err != nil {
155			return nil, err
156		}
157		deps := requestDeps(&req)
158		if req.RequestID != "" {
159			key := idemIdentity{req.Submitter, req.RequestID}
160			if origID, ok := s.idem[key]; ok {
161				orig := s.byID[origID]
162				if sameContent(orig, &req) {
163					return s.viewLocked(orig), nil
164				}
165				return s.viewLocked(orig),
166					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d",
167						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID)
168			}
169		}
170	
171		now := s.now().UTC()
172		j := &storedJob{
173			id:           s.nextID,
174			submitter:    req.Submitter,
175			requestID:    req.RequestID,
176			seed:         req.Seed,
177			values:       append([]int64(nil), req.Values...),
178			dependencies: append([]uint64(nil), deps...),
179			queuedAt:     now,
180			status:       StatusQueued,
181		}
182		// 先持久化，接受之后该提交即不可丢失。
183		if err := s.persist(j); err != nil {
184			return nil, err
185		}
186		s.nextID++
187		s.jobs = append(s.jobs, j)
188		s.byID[j.id] = j
189		if req.RequestID != "" {
190			s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
191		}
192		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
193		s.cascadeLocked()
194		s.notifyLocked()
195		return s.viewLocked(j), nil
196	}
197	
198	// requestDeps 规范化一次提交的直接上游作业号列表：
199	// 非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含一个作业号的列表；
200	// 两者皆无则为 nil。调用前须先经 [Store.validateDependenciesLocked] 校验。
201	func requestDeps(req *SubmitRequest) []uint64 {
202		if len(req.Dependencies) > 0 {
203			return append([]uint64(nil), req.Dependencies...)
204		}
205		if req.HasDependency {
206			return []uint64{req.DependencyID}
207		}
208		return nil
209	}
210	
211	// validateDependenciesLocked 在持锁状态下校验提交的依赖列表：
212	//   - 单依赖方式与非空列表同时启用 → 拒绝；
213	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）；
214	//   - 列表引用提交时不存在的作业 → 拒绝。
215	//
216	// 任一拒绝都不产生记录，也不占用幂等请求号。
217	func (s *Store) validateDependenciesLocked(req *SubmitRequest) error {
218		if req.HasDependency && len(req.Dependencies) > 0 {
219			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
220		}
221		deps := requestDeps(req)
222		seen := make(map[uint64]struct{}, len(deps))
223		for _, id := range deps {
224			if id == 0 {
225				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
226			}
227			if _, dup := seen[id]; dup {
228				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
229			}
230			seen[id] = struct{}{}
231		}
232		for _, id := range deps {
233			if s.byID[id] == nil {
234				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
235			}
236		}
237		return nil
238	}
239	
240	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
241	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
242	func sameContent(j *storedJob, req *SubmitRequest) bool {
243		if j.seed != req.Seed {
244			return false
245		}
246		rd := requestDeps(req)
247		if len(j.dependencies) != len(rd) {
248			return false
249		}
250		for i := range j.dependencies {
251			if j.dependencies[i] != rd[i] {
252				return false
253			}
254		}
255		if len(j.values) != len(req.Values) {
256			return false
257		}
258		for i := range j.values {
259			if j.values[i] != req.Values[i] {
260				return false
261			}
262		}
263		return true
264	}
265	
266	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
267	func (s *Store) Get(id uint64) (*Job, error) {
268		s.mu.Lock()
269		defer s.mu.Unlock()
270		j := s.byID[id]
271		if j == nil {
272			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
273		}
274		return s.viewLocked(j), nil
275	}
276	
277	// Cancel 请求取消作业。
278	//
279	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
280	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
281	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
282	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
283	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
284	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
285	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
286	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
287	func (s *Store) Cancel(id uint64) (*Job, error) {
288		s.mu.Lock()
289		defer s.mu.Unlock()
290		if s.closed {
291			return nil, ErrStoreClosed
292		}
293		j := s.byID[id]
294		if j == nil {
295			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
296		}
297		switch j.status {
298		case StatusCanceled:
299			return s.viewLocked(j), nil
300		case StatusSucceeded, StatusFailed:
301			return s.viewLocked(j),
302				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
303		}
304	
305		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
306		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
307		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
308		// 不能把这次取消当作已完成。
309		now := s.now().UTC()
310		prevStatus := j.status
311		prevFinishedAt := j.finishedAt
312		prevReason := j.failureReason
313		prevBlocker := j.blockerID
314		prevEffective := j.effectiveValues
315		prevArchive := j.archive
316		j.status = StatusCanceled
317		j.failureReason = ""
318		j.blockerID = 0
319		if j.finishedAt.IsZero() {
320			j.finishedAt = now
321		}
322		j.effectiveValues = nil
323		j.archive = nil
324		if err := s.persist(j); err != nil {
325			j.status = prevStatus
326			j.finishedAt = prevFinishedAt
327			j.failureReason = prevReason
328			j.blockerID = prevBlocker
329			j.effectiveValues = prevEffective
330			j.archive = prevArchive
331			return nil, err
332		}
333	
334		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
335		j.canceled.Store(true)
336		// 依赖它的等待者一并失败，且继续向更下游传播。
337		s.cascadeLocked()
338		s.notifyLocked()
339		return s.viewLocked(j), nil
340	}
341	
342	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
343	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
344	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
345		s.mu.Lock()
346		defer s.mu.Unlock()
347		if !start.IsZero() && !end.IsZero() && start.After(end) {
348			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
349				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
350		}
351		out := make([]*Job, 0)
352		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
353			if j.submitter != submitter {
354				continue
355			}
356			if !start.IsZero() && j.queuedAt.Before(start) {
357				continue
358			}
359			if !end.IsZero() && j.queuedAt.After(end) {
360				continue
361			}
362			out = append(out, s.viewLocked(j))
363		}
364		return out, nil
365	}
366	
367	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
368	//
369	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
370	// 扫描即可让阻断沿链条传播到最下游。作业有多个直接上游时，按列表顺序
371	// 选取最靠前的已失败/取消者作为直接阻断者；作业一旦失败，其原因不再被
372	// 后来发生的上游状态变化改写。
373	func (s *Store) cascadeLocked() {
374		for _, j := range s.jobs {
375			if j.status != StatusQueued || len(j.dependencies) == 0 {
376				continue
377			}
378			var direct *storedJob
379			for _, id := range j.dependencies {
380				dep := s.byID[id]
381				if dep == nil {
382					continue
383				}
384				if dep.status == StatusFailed || dep.status == StatusCanceled {
385					direct = dep
386					break
387				}
388			}
389			if direct == nil {
390				continue
391			}
392			root := direct.blockerID
393			if root == 0 {
394				root = direct.id
395			}
396			s.markFailedLocked(j, blockedReason(direct, root), root)
397		}
398	}
399	
400	func blockedReason(dep *storedJob, root uint64) string {
401		state := "失败"
402		if dep.status == StatusCanceled {
403			state = "被取消"
404		}
405		reason := fmt.Sprintf("直接上游作业 %d 已%s，阻断本作业继续计算", dep.id, state)
406		if dep.status == StatusFailed && dep.failureReason != "" {
407			reason += "（其失败原因：" + dep.failureReason + "）"
408		}
409		if root != dep.id {
410			reason += fmt.Sprintf("；阻断根因为作业 %d", root)
411		}
412		return reason
413	}
414	
415	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
416	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
417	// 该作业就被跳过，不挡住后面可运行的作业。
418	func (s *Store) pickRunnableLocked() *storedJob {
419		for _, j := range s.jobs {
420			if j.status != StatusQueued {
421				continue
422			}
423			if len(j.dependencies) == 0 {
424				return j
425			}
426			ready := true
427			for _, id := range j.dependencies {
428				dep := s.byID[id]
429				if dep == nil || dep.status != StatusSucceeded {
430					ready = false
431					break
432				}
433			}
434			if ready {
435				return j
436			}
437		}
438		return nil
439	}
440	
441	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
442	func (s *Store) notifyLocked() {
443		select {
444		case s.waitCh <- struct{}{}:
445		default:
446		}
447	}
448	
449	// notify 在不持锁时唤醒 worker。
450	func (s *Store) notify() {
451		s.mu.Lock()
452		s.notifyLocked()
453		s.mu.Unlock()
454	}
455	
456	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
457	func (s *Store) persistRetry(j *storedJob, attempts int) error {
458		var err error
459		for i := 0; i < attempts; i++ {
460			if err = s.persist(j); err == nil {
461				return nil
462			}
463		}
464		return err
465	}
466	
467	// worker 是本地唯一的计算执行体。
468	func (s *Store) worker() {
469		defer s.wg.Done()
470		for {
471			s.mu.Lock()
472			if s.stopping.Load() {
473				s.mu.Unlock()
474				return
475			}
476			j := s.pickRunnableLocked()
477			if j == nil {
478				ch := s.waitCh
479				s.mu.Unlock()
480				select {
481				case <-ch:
482				case <-s.stopCh:
483				}
484				continue
485			}
486	
487			// 进入运行并原子持久化该状态。
488			j.status = StatusRunning
489			j.startedAt = s.now().UTC()
490			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
491			inputs := append([]int64(nil), j.values...)
492			for _, id := range j.dependencies {
493				if dep := s.byID[id]; dep != nil && dep.archive != nil {
494					inputs = append(inputs, dep.archive.Sum)
495				}
496			}
497			seed := j.seed
498			s.runningID = j.id
499			if err := s.persistRetry(j, 3); err != nil {
500				// 连运行状态都无法落盘：保守地失败，不进行计算。
501				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
502				s.runningID = 0
503				s.cascadeLocked()
504				s.notifyLocked()
505				s.mu.Unlock()
506				continue
507			}
508			s.mu.Unlock()
509	
510			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
511			doCompute := s.compute
512			if doCompute == nil {
513				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
514					return computeResult(in, sd, c)
515				}
516			}
517			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
518	
519			s.mu.Lock()
520			s.runningID = 0
521			switch {
522			case j.status == StatusCanceled:
523				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
524				j.archive = nil
525				j.effectiveValues = nil
526				_ = s.persistRetry(j, 3)
527				s.cascadeLocked()
528			case s.stopping.Load():
529				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
530				s.cascadeLocked()
531			case !ok:
532				s.markFailedLocked(j, reason, 0)
533				s.cascadeLocked()
534			default:
535				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
536				completed := s.now().UTC()
537				a := newArchive(j, inputs, sum, sumSq, completed)
538				j.effectiveValues = append([]int64(nil), inputs...)
539				j.status = StatusSucceeded
540				j.finishedAt = completed
541				j.failureReason = ""
542				j.blockerID = 0
543				j.archive = a
544				if err := s.persistRetry(j, 3); err != nil {
545					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
546					j.archive = nil
547					j.effectiveValues = nil
548					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
549					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
550					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
551					s.cascadeLocked()
552				}
553			}
554			s.notifyLocked()
555			s.mu.Unlock()
556		}
557	}
558	
559	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
560	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
561		j.status = StatusFailed
562		j.failureReason = reason
563		j.blockerID = blocker
564		if j.finishedAt.IsZero() {
565			j.finishedAt = s.now().UTC()
566		}
567		j.archive = nil
568		j.effectiveValues = nil
569		_ = s.persistRetry(j, 3)
570	}
571	
572	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
573	// 上游作业号只作记录，不参与任何摘要与校验值。
574	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
575		inDigest := inputsDigestHex(effective, j.seed)
576		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
577		log := buildLog(effective, j.seed, sum, sumSquares)
578		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
579		var firstDep uint64
580		if len(j.dependencies) > 0 {
581			firstDep = j.dependencies[0]
582		}
583		return &Archive{
584			JobID:           j.id,
585			Submitter:       j.submitter,
586			RequestID:       j.requestID,
587			IdentityRaw:     rawIdentity(j.submitter, j.requestID),
588			Seed:            j.seed,
589			Values:          append([]int64(nil), j.values...),
590			HasDependency:   len(j.dependencies) > 0,
591			DependencyID:    firstDep,
592			Dependencies:    append([]uint64(nil), j.dependencies...),
593			EffectiveValues: append([]int64(nil), effective...),
594			InputsDigest:    inDigest,
595			Sum:             sum,
596			SumOfSquares:    sumSquares,
597			ResultDigest:    resDigest,
598			Log:             log,
599			Checksum:        checksum,
600			CompletedAt:     completedAt,
601		}
602	}
603	
604	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
605	func (s *Store) viewLocked(j *storedJob) *Job {
606		v := &Job{
607			ID:              j.id,
608			Submitter:       j.submitter,
609			RequestID:       j.requestID,
610			Seed:            j.seed,
611			Values:          append([]int64(nil), j.values...),
612			Dependencies:    append([]uint64(nil), j.dependencies...),
613			QueuedAt:        j.queuedAt,
614			StartedAt:       j.startedAt,
615			FinishedAt:      j.finishedAt,
616			Status:          j.status,
617			FailureReason:   j.failureReason,
618			BlockerID:       j.blockerID,
619			EffectiveValues: append([]int64(nil), j.effectiveValues...),
620		}
621		v.HasDependency = len(j.dependencies) > 0
622		if len(j.dependencies) > 0 {
623			v.DependencyID = j.dependencies[0]
624		}
625		if j.status == StatusQueued {
626			v.WaitReason = WaitSlot
627			// 列出尚未成功归档的直接上游，保持提交时的顺序。
628			for _, id := range j.dependencies {
629				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
630					v.PendingDependencies = append(v.PendingDependencies, id)
631				}
632			}
633			if len(v.PendingDependencies) > 0 {
634				v.WaitReason = WaitDependency
635			}
636		}
637		if j.archive != nil {
638			a := *j.archive
639			a.Values = append([]int64(nil), j.archive.Values...)
640			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
641			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
642			if j.archive.IdentityRaw != nil {
643				raw := *j.archive.IdentityRaw
644				a.IdentityRaw = &raw
645			}
646			v.Archive = &a
647		}
648		return v
649	}
650	
651	// Dir 返回归档目录路径。
652	func (s *Store) Dir() string { return s.dir }
653

