242	// loadDir 扫描目录中的全部作业记录并重建内存索引。
243	//
244	// 恢复规则：
245	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
246	//   - 成功记录缺少归档或校验值对不上时 fail-closed 地标记为失败，
247	//     维持“成功必有完整归档”的不变量。
248	func loadDir(dir string) ([]*storedJob, uint64, error) {
249		entries, err := os.ReadDir(dir)
250		if err != nil {
251			return nil, 0, err
252		}
253		var jobs []*storedJob
254		var maxID uint64
255		for _, e := range entries {
256			name := e.Name()
257			if e.IsDir() {
258				continue
259			}
260			// 清理上一进程崩溃时可能残留的原子写临时文件。
261			if strings.HasPrefix(name, ".tmp-") {
262				_ = os.Remove(filepath.Join(dir, name))
263				continue
264			}
265			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
266				continue
267			}
268			path := filepath.Join(dir, name)
269			data, err := os.ReadFile(path)
270			if err != nil {
271				return nil, 0, err
272			}
273			var r jobRecord
274			if err := json.Unmarshal(data, &r); err != nil {
275				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
276			}
277			if r.Version != recordVersion {
278				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
279			}
280			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
281			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
282			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
283			if err != nil {
284				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
285			}
286			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
287			// 与归档中的参数逐字节一致。
288			if r.Archive != nil {
289				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
290				if aErr != nil {
291					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
292				}
293				r.Archive.Submitter = aSub
294				r.Archive.RequestID = aReq
295			}
296			switch r.Status {
297			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
298			default:
299				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
300			}
301			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
302			// 恢复为只含一个作业号的列表（语义与提交时一致）。
303			deps := append([]uint64(nil), r.Dependencies...)
304			if len(deps) == 0 && r.HasDependency {
305				deps = []uint64{r.DependencyID}
306			}
307			j := &storedJob{
308				id:           r.ID,
309				submitter:    submitter,
310				requestID:    requestID,
311				seed:         r.Seed,
312				values:       append([]int64(nil), r.Values...),
313				dependencies: deps,
314	
315				queuedAt:   r.QueuedAt,
316				startedAt:  r.StartedAt,
317				finishedAt: r.FinishedAt,
318	
319				status:        r.Status,
320				failureReason: r.FailureReason,
321				blockerID:     r.BlockerID,
322	
323				effectiveValues: append([]int64(nil), r.EffectiveValues...),
324				archive:         r.Archive,
325			}
326			if j.status == StatusRunning {
327				j.status = StatusFailed
328				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
329				j.blockerID = 0
330				if j.finishedAt.IsZero() {
331					j.finishedAt = time.Now().UTC()
332				}
333				j.effectiveValues = nil
334				j.archive = nil
335				// 就地重写恢复后的终态。
336				if data, err := encodeRecord(j); err == nil {
337					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
338				}
339			}
340			if j.status == StatusSucceeded && !archiveIntact(j) {
341				j.status = StatusFailed
342				j.failureReason = "归档不完整或校验值不一致，成功结果不可用"
343				if j.finishedAt.IsZero() {
344					j.finishedAt = time.Now().UTC()
345				}
346				j.effectiveValues = nil
347				j.archive = nil
348				if data, err := encodeRecord(j); err == nil {
349					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
350				}
351			}
352			jobs = append(jobs, j)
353			if j.id > maxID {
354				maxID = j.id
355			}
356		}
357		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
358		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
359		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
360		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
361		// 依赖链在单趟级联扫描中漏掉失败传播）。
362		sort.Slice(jobs, func(a, b int) bool {
363			return jobs[a].id < jobs[b].id
364		})
365		return jobs, maxID, nil
366	}
367	
368	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
369	func archiveIntact(j *storedJob) bool {
370		a := j.archive
371		if a == nil {
372			return false
373		}
374		// 归档中的原始参数必须与记录顶层字段一致。
375		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
376			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
377			return false
378		}
379		if a.HasDependency && a.DependencyID != depID(j) {
380			return false
381		}
382		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
383		// 由单依赖字段推导后再比较。
384		aDeps := append([]uint64(nil), a.Dependencies...)
385		if len(aDeps) == 0 && a.HasDependency {
386			aDeps = []uint64{a.DependencyID}
387		}
388		if len(aDeps) != len(j.dependencies) {
389			return false
390		}
391		for i := range j.dependencies {
392			if aDeps[i] != j.dependencies[i] {
393				return false
394			}
395		}
396		if len(a.Values) != len(j.values) {
397			return false
398		}
399		for i := range j.values {
400			if a.Values[i] != j.values[i] {
401				return false
402			}
403		}
404		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
405			return false
406		}
407		for i := range j.effectiveValues {
408			if j.effectiveValues[i] != a.EffectiveValues[i] {
409				return false
410			}
411		}
412		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
413			return false
414		}
415		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
416			return false
417		}
418		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
419			return false
420		}
421		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
422			return false
423		}
424		return true
425	}
